{"command":"node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { parsePo } from './tools/i18n-engine/src/po.ts';
for (const locale of ['ar', 'fa', 'hi', 'th']) {
  const path = `l10n/${locale}/docs.guides.po`;
  const original = execFileSync('git', ['show', `HEAD^:${path}`], {encoding: 'utf8'});
  const current = readFileSync(path, 'utf8');
  const currentBlock = current.split('\n\n').find(block => block.includes('#: guide/cli.md\n'));
  assert.ok(currentBlock);
  const replacement = currentBlock.slice(currentBlock.indexOf('\nmsgstr ') + 1);
  let replaced = 0;
  const updated = original.split('\n\n').map(block => {
    if (!block.includes('#: guide/cli.md\n')) return block;
    const start = block.indexOf('\nmsgstr ');
    assert.ok(start !== -1);
    replaced++;
    return block.slice(0, start + 1) + replacement;
  }).join('\n\n');
  assert.equal(replaced, 1);
  assert.equal(parsePo(updated).length, parsePo(original).length);
  writeFileSync(path, updated);
  console.log(`${locale}: preserved all original catalog entries`);
}
NODE","explanation":"Repair the mechanical rewrite to preserve obsolete entries and replace only the CLI translation block.","goal":"Remove unintended catalog churn","mode":"sync"}

